create table t1(a integer primary key, b text, c blob);
create index t1b on t1(b);
create table t2(x, y) ;
create view v1 as select a, b from t1;
create trigger tr1 after insert on t2 begin insert into t1(b) values(new.x); end;
with recursive n(i) as (select 1 union all select i+1 from n where i < 2000) insert into t1(b, c) select 'row ' || i, randomblob(100) from n;
insert into t2 values('hello', 1);
pragma page_count;
delete from t1 where a % 3 <> 0;
pragma freelist_count;
vacuum;
pragma page_count;
pragma freelist_count;
pragma integrity_check;
select count(*), min(a), max(a) from t1;
select name, type from sqlite_schema order by name;
pragma page_size = 8192;
vacuum;
pragma page_size;
pragma page_count;
pragma auto_vacuum = 1;
vacuum;
pragma auto_vacuum;
delete from t1 where a > 3000;
pragma freelist_count;
pragma integrity_check;
begin;
vacuum;
rollback;
vacuum temp;
vacuum main;
vacuum into 'vac_into.db';
vacuum into 'vac_into.db';
vacuum into 123;
attach 'vac_into.db' as vi;
select count(*) from vi.t1;
pragma vi.page_size;
pragma vi.integrity_check;
select name from vi.sqlite_schema order by name;
detach vi;
select random() is not null;
